*{box-sizing:border-box} :root{--ink:#24352e;--muted:#82918a;--paper:#f6f5ee;--white:#fffefa;--line:#e7e9df;--green:#347c58;--green-dark:#235c40;--mint:#eaf3e9;--orange:#f4a04f;--shadow:0 12px 35px rgba(37,56,45,.07)}
body{margin:0;background:#f6f5ee;color:var(--ink);font-family:'Nunito',sans-serif;min-height:100vh}.app-shell{max-width:1512px;margin:0 auto;padding:0 42px}.topbar{height:88px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e8e9df}.brand{display:flex;align-items:center;gap:11px;color:var(--ink);font-weight:900;letter-spacing:1.55px;font-size:15px;text-decoration:none}.brand-mark{width:37px;height:37px;border-radius:12px;background:#dff0dc;color:#438a59;display:grid;place-items:center;font-size:22px;box-shadow:inset 0 0 0 1px #cee4ce}.brand-sub{display:block;color:#9aa39b;font:500 9px 'DM Mono',monospace;letter-spacing:1.1px;margin-top:3px}.top-stats{display:flex;align-items:center;gap:42px;margin-left:40px}.stat{position:relative;display:flex;align-items:center;gap:10px;min-width:102px}.stat-icon{display:grid;place-items:center;width:34px;height:34px;border-radius:11px;background:#edf3e9;color:#4a9860;font-size:18px}.hp-stat .stat-icon{color:#e77b73;background:#faece8}.energy-stat .stat-icon{color:#d99a3f;background:#fbf1dc}.wave-stat .stat-icon{color:#678fc4;background:#eaf0fa}.stat small{display:block;color:#9ba59c;font:500 9px 'DM Mono',monospace;letter-spacing:.8px;margin-bottom:1px}.stat strong{font:800 16px 'DM Mono',monospace;letter-spacing:-.4px}.stat strong i{font-style:normal;color:#a6afa7;font-size:12px}.hp-track{width:49px;height:4px;background:#eee7df;position:absolute;left:45px;bottom:-7px;border-radius:5px;overflow:hidden}.hp-track i{height:100%;width:100%;display:block;background:#e98077;border-radius:5px;transition:width .2s}.top-actions{display:flex;align-items:center;gap:16px}.save-state{font:500 9px 'DM Mono',monospace;letter-spacing:1px;color:#82948a}.save-state i,.eyebrow-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#7fbd78;margin-right:6px;vertical-align:1px}.icon-button,.square-button{border:1px solid var(--line);background:var(--white);color:#78877e;border-radius:10px;cursor:pointer;transition:.18s}.icon-button{width:37px;height:37px;font-size:17px}.icon-button:hover,.square-button:hover{border-color:#a9c5ae;color:var(--green)}
.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 337px;gap:30px;padding:31px 0 22px}.field-heading{display:flex;align-items:flex-end;justify-content:space-between;margin:0 4px 17px}.eyebrow{display:block;font:500 9px 'DM Mono',monospace;letter-spacing:1.05px;color:#98a49a}.field-heading h1{font-size:27px;line-height:1;margin:7px 0 0;letter-spacing:-.8px;font-weight:900}.field-heading h1 span{font-weight:600;color:#8a9a8d}.field-meta{display:flex;gap:17px;color:#8c9a8e;font:500 9px 'DM Mono',monospace;letter-spacing:.6px;padding-bottom:2px}.map-count b{color:#c3ccc2;padding:0 4px}.weather{color:#a37a3c}.board-wrap{position:relative;width:100%;aspect-ratio:900/525;border-radius:16px;border:1px solid #dfe6d9;overflow:hidden;background:#dbe9c7;box-shadow:var(--shadow)}canvas{display:block;width:100%;height:100%;touch-action:manipulation;cursor:crosshair}.map-corner{position:absolute;color:rgba(70,102,76,.56);font:500 8px 'DM Mono',monospace;letter-spacing:1px;pointer-events:none}.map-corner span{color:#88a47e;margin-left:4px}.corner-tl{top:12px;left:15px}.corner-br{right:14px;bottom:10px}.field-footer{height:49px;display:flex;align-items:center;justify-content:space-between;padding:0 4px}.path-key{font:500 8px 'DM Mono',monospace;color:#849189;letter-spacing:.45px}.key-dot,.key-tower,.key-base{color:#bd9d71;font-size:10px}.key-dot{display:inline-block;width:6px;height:6px;background:#c59e6c;border-radius:50%;margin-right:4px}.key-sep{color:#ccd2c9;margin:0 7px}.key-tower{color:#6b9b66}.key-base{color:#7096c2}.wave-progress{width:182px;display:flex;align-items:center;gap:9px;color:#98a299;font:500 8px 'DM Mono',monospace;letter-spacing:.4px}.progress-track{height:4px;background:#e6e9df;border-radius:4px;flex:1;overflow:hidden}.progress-track i{display:block;width:0;height:100%;background:#72aa6f;border-radius:4px;transition:width .3s}
.command-panel{align-self:start;background:var(--white);border:1px solid #e8e9e1;border-radius:16px;box-shadow:var(--shadow);padding:19px 18px 14px;min-height:610px}.wave-card{padding:0 1px 17px;border-bottom:1px solid #eceee8}.wave-card-top{display:flex;align-items:center;justify-content:space-between}.wave-card h2{font-size:18px;line-height:1.1;margin:5px 0 0;font-weight:900;letter-spacing:-.35px}.phase-badge{border-radius:20px;padding:6px 9px;background:#f1f3eb;color:#84938a;font:500 8px 'DM Mono',monospace;letter-spacing:.6px}.phase-badge.live{background:#fff0e4;color:#d58039}.wave-card p{color:#929d94;font-size:11px;line-height:1.5;margin:9px 0 13px;max-width:255px}.wave-buttons{display:flex;gap:7px}.primary-button{height:38px;border:0;border-radius:9px;background:#347c58;color:white;padding:0 14px;font:800 10px 'DM Mono',monospace;letter-spacing:.3px;box-shadow:0 4px 0 #286747;cursor:pointer;transition:.16s;flex:1}.primary-button span{font-size:9px;margin-right:6px}.primary-button:hover{background:#286d4b;transform:translateY(-1px);box-shadow:0 5px 0 #286747}.primary-button:active{transform:translateY(2px);box-shadow:0 2px 0 #286747}.primary-button:disabled{background:#a7b6aa;box-shadow:0 4px 0 #91a096;cursor:not-allowed;transform:none}.square-button{height:38px;width:39px;font:700 13px 'DM Mono',monospace}.square-button.active{background:#e8f3e8;border-color:#acd0ac;color:#347c58}.speed-button{width:45px;font-size:11px}.roster-section{padding:17px 0 14px}.section-title{display:flex;align-items:center;justify-content:space-between;margin:0 1px 11px}.section-title h2{font-size:14px;line-height:1;margin:4px 0 0;font-weight:900}.tiny-count{font:500 10px 'DM Mono',monospace;color:#a1aaa2;background:#f4f5ef;border-radius:6px;padding:5px 7px}.creature-list{display:grid;grid-template-columns:1fr 1fr;gap:7px}.creature-card{height:61px;border:1px solid #eaede6;border-radius:10px;background:#fffefa;display:flex;align-items:center;gap:8px;padding:7px 8px;cursor:pointer;position:relative;transition:.16s;text-align:left;color:var(--ink);min-width:0}.creature-card:hover{border-color:#bed6be;background:#fbfdf8;transform:translateY(-1px)}.creature-card.selected{border-color:#72ad7a;background:#f1f8ef;box-shadow:0 0 0 1px #72ad7a}.creature-card.locked{opacity:.55;cursor:not-allowed;background:#f7f7f2}.creature-avatar{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;font-size:19px;flex:none}.creature-info{min-width:0}.creature-name{font-size:10px;font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block}.creature-type{font:500 8px 'DM Mono',monospace;color:#8d9a90;display:block;margin-top:3px;white-space:nowrap}.creature-cost{position:absolute;right:6px;bottom:5px;color:#c2923f;font:500 8px 'DM Mono',monospace}.card-check{position:absolute;right:6px;top:5px;color:#4c9960;font-size:10px}
.selection-panel{border:1px solid #e9ece5;background:#fbfcf8;border-radius:11px;min-height:89px;padding:10px}.selection-empty{display:flex;align-items:center;gap:10px;height:65px;padding-left:4px}.empty-spark{width:31px;height:31px;border-radius:9px;background:#f0f3e9;color:#a2b18e;display:grid;place-items:center}.selection-empty strong,.selected-title{font-size:11px;display:block;font-weight:900}.selection-empty small{font-size:9px;color:#9ca59d;display:block;margin-top:3px}.selected-creature{display:flex;align-items:center;gap:9px}.selected-avatar{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;font-size:20px;flex:none}.selected-text{min-width:0;flex:1}.selected-meta{font:500 8px 'DM Mono',monospace;color:#94a096;display:block;margin-top:3px}.selected-actions{display:flex;gap:5px;margin-top:9px}.mini-action{height:26px;border:1px solid #dce5da;border-radius:7px;background:white;color:#427b53;padding:0 9px;font:700 8px 'DM Mono',monospace;cursor:pointer}.mini-action:hover{background:#edf5eb}.mini-action.sell{color:#a97868;border-color:#eddfd7}.panel-hint{margin:11px 1px 0;font:500 7px 'DM Mono',monospace;color:#aab2a9;letter-spacing:.5px}.panel-hint span{font-size:10px;color:#8aab8a;margin-right:4px}
.bottom-bar{height:55px;border-top:1px solid #e8e9df;display:flex;align-items:center;justify-content:space-between}.type-legend{display:flex;align-items:center;gap:7px}.legend-label{font:500 8px 'DM Mono',monospace;letter-spacing:.8px;color:#9ca69e;margin-right:4px}.type-chip{font:500 8px 'DM Mono',monospace;letter-spacing:.2px;padding:5px 7px;border-radius:5px}.type-chip.fire{color:#c77857;background:#faeee6}.type-chip.grass{color:#5d9564;background:#eaf4e8}.type-chip.water{color:#648eae;background:#eaf1f7}.type-arrow{color:#b4bdb4;font-size:12px}.legend-note{font:500 8px 'DM Mono',monospace;color:#929e94;margin-left:2px}.footer-tip{font-size:10px;color:#9da69d}.footer-tip span{color:#d9a552;margin-right:5px}.toast{position:absolute;top:16px;left:50%;transform:translate(-50%,-10px);background:#294f3b;color:white;border-radius:20px;padding:8px 14px;font:500 10px 'DM Mono',monospace;opacity:0;pointer-events:none;transition:.2s;white-space:nowrap;z-index:2;box-shadow:0 4px 14px #3456}.toast.show{opacity:1;transform:translate(-50%,0)}
.modal-backdrop,.end-overlay{position:fixed;inset:0;background:rgba(35,52,43,.43);backdrop-filter:blur(4px);display:grid;place-items:center;z-index:10;padding:18px}.hidden{display:none!important}.choice-modal,.end-card{width:min(580px,100%);background:#fffefa;border:1px solid #e7e9df;border-radius:20px;box-shadow:0 25px 90px #1e372744;padding:29px 30px 19px;text-align:center;position:relative}.choice-spark{position:absolute;right:25px;top:19px;font-size:23px;color:#e3ba69}.choice-modal .eyebrow,.end-card .eyebrow{color:#88a087}.choice-modal h2,.end-card h2{font-size:25px;font-weight:900;letter-spacing:-.7px;margin:7px 0 5px}.choice-modal>p,.end-card p{font-size:12px;color:#8f9b91;margin:0}.choice-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:22px 0 17px}.choice-card{border:1px solid #e6eae1;border-radius:12px;background:#fcfcf8;padding:14px 10px 12px;cursor:pointer;color:var(--ink);transition:.15s}.choice-card:hover{border-color:#88b48b;background:#f4f8ef;transform:translateY(-3px)}.choice-emoji{width:45px;height:45px;border-radius:14px;margin:0 auto 8px;display:grid;place-items:center;font-size:26px}.choice-card strong{display:block;font-size:12px}.choice-card small{display:block;color:#919e92;font:500 8px 'DM Mono',monospace;margin-top:4px}.choice-card em{display:block;color:#5a9565;font-style:normal;font-size:9px;font-weight:800;margin-top:8px}.choice-foot{border-top:1px solid #edf0e9;padding-top:12px;display:flex;justify-content:space-between;color:#9aa49a;font:500 8px 'DM Mono',monospace;letter-spacing:.5px}.choice-foot span:last-child{color:#76a178}.end-card{width:min(390px,100%);padding:34px}.end-icon{display:grid;place-items:center;width:58px;height:58px;border-radius:20px;margin:0 auto 15px;background:#eaf4e6;color:#63a367;font-size:30px}.end-card h2{margin-bottom:6px}.end-card p{line-height:1.55;margin-bottom:22px}.end-card .primary-button{flex:none;padding:0 27px}
@media(max-width:1050px){.app-shell{padding:0 24px}.game-layout{grid-template-columns:minmax(0,1fr) 305px;gap:20px}.top-stats{gap:22px}.command-panel{padding:16px 14px}.creature-card{gap:5px;padding:6px}.creature-cost{right:5px}}
@media(max-width:780px){.app-shell{padding:0 14px}.topbar{height:69px}.brand{font-size:13px}.brand-mark{width:32px;height:32px}.top-stats{gap:13px;margin:0}.stat{gap:6px;min-width:auto}.stat-icon{width:29px;height:29px;font-size:15px}.stat strong{font-size:13px}.stat small{font-size:7px}.hp-track{display:none}.save-state{display:none}.game-layout{display:flex;flex-direction:column;gap:14px;padding-top:20px}.field-heading{margin-bottom:12px}.field-heading h1{font-size:23px}.field-meta{font-size:8px;gap:9px}.command-panel{min-height:0;padding:15px}.roster-section{padding:14px 0}.creature-list{grid-template-columns:repeat(3,1fr)}.creature-card{height:58px}.selection-panel{min-height:75px}.selection-empty{height:54px}.field-footer{height:43px}.path-key{font-size:7px}.wave-progress{width:150px}.panel-hint{margin-top:8px}.bottom-bar{height:auto;min-height:49px;gap:8px;flex-wrap:wrap;padding:9px 0}.footer-tip{display:none}}
@media(max-width:480px){.app-shell{padding:0 10px}.brand{letter-spacing:.8px;font-size:11px;gap:7px}.brand-sub{font-size:7px}.topbar{height:61px}.top-stats{gap:9px}.stat{gap:4px}.stat-icon{width:25px;height:25px;border-radius:8px}.stat small{font-size:6px}.stat strong{font-size:11px}.top-actions{gap:0}.icon-button{width:30px;height:30px}.wave-stat{display:none}.game-layout{padding-top:16px}.field-heading h1{font-size:20px}.weather{display:none}.map-count{font-size:7px}.field-footer{align-items:flex-start;padding-top:9px;height:42px}.wave-progress{width:127px;font-size:7px}.key-sep{margin:0 3px}.path-key{font-size:6px}.command-panel{padding:13px 11px}.creature-list{gap:5px}.creature-card{height:55px;padding:5px;gap:4px}.creature-avatar{width:28px;height:28px;font-size:16px;border-radius:8px}.creature-name{font-size:9px}.creature-type{font-size:7px}.creature-cost{font-size:7px}.choice-modal{padding:25px 15px 15px}.choice-cards{gap:6px}.choice-card{padding:10px 5px}.choice-modal h2{font-size:21px}.choice-emoji{width:39px;height:39px;font-size:23px}.legend-label{display:none}.legend-note{font-size:7px}.type-chip{font-size:7px;padding:5px 5px}}

(() => {
  'use strict';
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const W = 900, H = 525, COLS = 12, ROWS = 7, CELL = 68, OX = 42, OY = 24;
  const types = {
    fire:{name:'Cindercub',type:'FIRE',emoji:'🦊',color:'#f19a62',pale:'#fff0df',cost:85,range:145,rate:.95,damage:23,ability:'area damage',evolutions:['Cindercub','Blazetail','Sunflare']},
    water:{name:'Bubblot',type:'WATER',emoji:'🐸',color:'#72b9d1',pale:'#e5f5f8',cost:90,range:158,rate:1.15,damage:17,ability:'slow',evolutions:['Bubblot','Tidehop','Coralord']},
    grass:{name:'Spriglet',type:'GRASS',emoji:'🦔',color:'#8fc77d',pale:'#edf6e6',cost:80,range:145,rate:1.25,damage:15,ability:'poison',evolutions:['Spriglet','Brambleback','Verdantusk']},
    electric:{name:'Zappup',type:'ELECTRIC',emoji:'🐰',color:'#edca62',pale:'#fff7db',cost:105,range:175,rate:.78,damage:20,ability:'stun',evolutions:['Zappup','Voltusk','Thundhare']},
    rock:{name:'Pebblit',type:'ROCK',emoji:'🐻',color:'#aa9786',pale:'#f1ece6',cost:95,range:125,rate:1.3,damage:30,ability:'area damage',evolutions:['Pebblit','Boulderbear','Granititan']},
    wind:{name:'Flitfin',type:'WIND',emoji:'🐦',color:'#83b8a7',pale:'#e8f4ef',cost:100,range:190,rate:.55,damage:13,ability:'slow',evolutions:['Flitfin','Gustwing','Skyseraph']}
  };
  const path = [[0,5],[1,5],[2,5],[3,5],[3,4],[3,3],[4,3],[5,3],[6,3],[6,4],[6,5],[7,5],[8,5],[8,4],[8,3],[9,3],[10,3],[10,2],[10,1],[11,1]];
  const pathCenters = path.map(([x,y])=>({x:OX+x*CELL+CELL/2,y:OY+y*CELL+CELL/2}));
  const state = {hp:20,maxHp:20,energy:260,wave:0,totalWaves:10,phase:'prep',paused:false,speed:1,selectedType:'fire',selectedTower:null,unlocked:['fire','water','grass'],towers:[],enemies:[],projectiles:[],particles:[],floats:[],spawnLeft:0,spawnTimer:0,spawnInterval:.9,frame:0,toastTimer:0,offerTypes:[],waveStartCount:0};
  const pathCells = new Set(path.map(([x,y])=>`${x},${y}`));
  const $ = id => document.getElementById(id);
  const rand = (a,b)=>a+Math.random()*(b-a);
  const clamp = (v,a,b)=>Math.max(a,Math.min(b,v));

  function resize(){
    const r=canvas.getBoundingClientRect(), dpr=Math.min(window.devicePixelRatio||1,2);
    canvas.width=Math.round(r.width*dpr); canvas.height=Math.round(r.height*dpr);
    ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);
    ctx.imageSmoothingEnabled=false;
  }
  window.addEventListener('resize',resize); resize();
  function tileCenter(x,y){return {x:OX+x*CELL+CELL/2,y:OY+y*CELL+CELL/2};}
  function tileAt(px,py){const x=Math.floor((px-OX)/CELL),y=Math.floor((py-OY)/CELL);return x>=0&&x<COLS&&y>=0&&y<ROWS?{x,y}:null;}
  function showToast(text){const el=$('toast');el.textContent=text;el.classList.add('show');state.toastTimer=1.5;}
  function renderRoster(){
    const list=$('creatureList');list.innerHTML='';
    for(const key of state.unlocked){const c=types[key],b=document.createElement('button');b.className='creature-card'+(state.selectedType===key&&!state.selectedTower?' selected':'');b.innerHTML=`<span class="creature-avatar" style="background:${c.pale}">${c.emoji}</span><span class="creature-info"><span class="creature-name">${c.name}</span><span class="creature-type">${c.type} · ${c.ability.toUpperCase()}</span></span><span class="creature-cost">✦ ${c.cost}</span>`;
      b.addEventListener('click',()=>{state.selectedType=key;state.selectedTower=null;renderAllUI();showToast(`${c.name} ready to place`);});list.appendChild(b);
    }
    $('rosterCount').textContent=String(state.unlocked.length).padStart(2,'0');
  }
  function renderSelection(){
    const box=$('selectionPanel');
    if(state.selectedTower){const t=state.selectedTower,c=types[t.kind],name=c.evolutions[t.level-1],next=c.evolutions[t.level];
      box.innerHTML=`<div class="selected-creature"><span class="selected-avatar" style="background:${c.pale}">${c.emoji}</span><div class="selected-text"><span class="selected-title">${name} <span style="color:#a6b0a7;font-weight:600">· STAGE ${t.level}</span></span><span class="selected-meta">${c.type} · ${c.ability.toUpperCase()} · DMG ${Math.round(c.damage*(1+(t.level-1)*.65))}</span></div></div><div class="selected-actions"><button class="mini-action" id="upgradeBtn">${next?`⬆ EVOLVE · ✦ ${upgradeCost(t)}`:'✧ MAX EVOLUTION'}</button><button class="mini-action sell" id="sellBtn">SELL · ✦ ${Math.floor(t.invested*.7)}</button></div>`;
      const up=$('upgradeBtn');if(next)up.addEventListener('click',upgradeSelected);else up.disabled=true;
      $('sellBtn').addEventListener('click',sellSelected);
    }else{
      box.innerHTML=`<div class="selection-empty"><span class="empty-spark">✦</span><div><strong>Nothing selected</strong><small>Pick a creature, then tap an empty tile</small></div></div>`;
    }
  }
  function renderAllUI(){renderRoster();renderSelection();updateHud();}
  function upgradeCost(t){return t.level===1?100:160;}
  function updateHud(){
    $('hpValue').innerHTML=`${state.hp} <i>/ ${state.maxHp}</i>`;$('hpBar').style.width=`${100*state.hp/state.maxHp}%`;
    $('energyValue').textContent=state.energy;$('waveValue').innerHTML=`${state.wave} <i>/ ${state.totalWaves}</i>`;
    const live=state.phase==='wave';$('waveButton').disabled=live||state.phase==='ended'||state.phase==='choice';
    $('waveButton').innerHTML=live?`<span>●</span> WAVE ${state.wave} IN PROGRESS`:state.wave>=state.totalWaves?'<span>✓</span> TRAIL SECURE':`<span>▶</span> START WAVE ${state.wave+1}`;
    $('phaseTitle').textContent=live?'Wild ones incoming!':state.phase==='choice'?'A new friend awaits':state.phase==='ended'?'Trail defended!':'A quiet moment';
    $('phaseCopy').textContent=live?`${state.enemies.length+state.spawnLeft} wild creatures still on the trail. Keep them away from your base!`:state.phase==='prep'?'Choose a companion and place them beside the trail. The wild ones are coming.':state.phase==='choice'?'Choose a new companion to add to your team.':'Your companions are holding the line.';
    $('phaseBadge').textContent=live?'UNDER ATTACK':state.phase==='choice'?'REWARD':'PREP';$('phaseBadge').classList.toggle('live',live);
    $('waveLabel').textContent=live?`${state.enemies.length+state.spawnLeft} WILD ON TRAIL`:'PREPARE YOUR DEFENSE';
    const progress=live?100*(state.waveStartCount-state.spawnLeft-state.enemies.length)/state.waveStartCount:state.wave>=state.totalWaves?100:0;
    $('waveProgress').style.width=`${clamp(progress,0,100)}%`;
    $('pauseButton').classList.toggle('active',state.paused);$('pauseButton').textContent=state.paused?'▶':'Ⅱ';$('speedButton').textContent=`${state.speed}×`;
  }

  function startWave(){
    if(state.phase!=='prep'||state.wave>=state.totalWaves)return;
    state.wave++;state.phase='wave';state.paused=false;
    const n=7+state.wave*2+(state.wave===10?1:0);state.spawnLeft=n;state.waveStartCount=n;state.spawnTimer=.25;state.spawnInterval=Math.max(.43,.88-state.wave*.035);
    renderAllUI();showToast(state.wave===10?'THE MEADOW GUARDIAN APPROACHES!':`WAVE ${state.wave} · STAY SHARP!`);
  }
  function chooseOffer(){
    if(state.wave>=state.totalWaves){state.phase='ended';renderAllUI();showEnd(true);return;}
    state.phase='choice';state.paused=false;
    const unowned=Object.keys(types).filter(k=>!state.unlocked.includes(k));
    state.offerTypes=[];
    if(unowned.length){const shuffled=unowned.sort(()=>Math.random()-.5);state.offerTypes=shuffled.slice(0,Math.min(3,shuffled.length));}
    else state.offerTypes=Object.keys(types).sort(()=>Math.random()-.5).slice(0,3);
    renderAllUI();showChoices();
  }
  function showChoices(){
